// Local, zero-cloud-cost integration: real project handlers + real PostgreSQL.
// Stripe signatures are generated by the official SDK; payment facts and
// OpenAI text are deterministic mocks. No outbound payment/API requests.
import assert from 'node:assert/strict';
import { accountSnapshot } from '../packages/core/src/account.ts';
import { generatePaidReading } from '../packages/core/src/ai-reading.ts';
import { createTestCheckout } from '../packages/core/src/billing/checkout.ts';
import { settleStripeWebhook } from '../packages/core/src/billing/settle.ts';
import { StripeProvider } from '../packages/core/src/billing/stripe.ts';
import { redeemPackRequest } from '../packages/core/src/pack-redemption.ts';
import { paidReadingResponse } from '../packages/core/src/reading.ts';
import site from '../sites/yuelao/site.config.ts';
import { LocalQaDatabase } from './local-qa-postgrest.mjs';

if (!process.env.LOCAL_QA_DATABASE_URL) {
  throw new Error('LOCAL_QA_DATABASE_URL must point to an ephemeral loopback database');
}
const db = new LocalQaDatabase(process.env.LOCAL_QA_DATABASE_URL);
const mainUser = { id: '00000000-0000-4000-8000-000000000001', email: 'local-qa-owner@example.invalid' };
const otherUser = { id: '00000000-0000-4000-8000-000000000002', email: 'local-qa-other@example.invalid' };
const baseUrl = 'https://local-test.example.invalid';
const secret = 'whsec_local_qa_no_real_payment';
const provider = new StripeProvider({
  secretKey: 'sk_test_local_qa_no_real_payment',
  webhookSecret: secret,
  automaticTax: false,
});
const stripe = provider.stripe;
let checkoutCount = 0;
let aiCalls = 0;

provider.createCustomer = async ({ id }) => {
  assert.equal(id, mainUser.id);
  return 'cus_test_local_e2e_001';
};
// Prices are an owner decision in site.config.ts; the test follows the config, not a literal.
const PACK3 = site.products.find((p) => p.id === 'pack_3').prices['zh-Hant'];
// The live catalogue sells no item yet (outfits are free), so the item flow runs against the
// real config plus one QA-only item.
const ITEM = {
  id: 'qa_item',
  kind: 'item',
  name: 'QA item',
  prices: {
    'zh-Hant': { amount: 399, currency: PACK3.currency },
    'zh-Hans': { amount: 399, currency: PACK3.currency },
  },
};
const itemSite = { ...site, products: [...site.products, ITEM] };
const ITEM_PRICE = ITEM.prices['zh-Hant'];
let expecting = { id: 'pack_3', price: PACK3 };
provider.createCheckout = async (request) => {
  checkoutCount++;
  assert.equal(request.product.id, expecting.id);
  assert.equal(request.product.price.amount, expecting.price.amount);
  assert.equal(request.product.price.currency, expecting.price.currency);
  assert.ok(request.successUrl.startsWith(`${baseUrl}/billing/return?order=`));
  assert.equal(new URL(request.cancelUrl).origin, baseUrl);
  return {
    checkoutRef: `cs_test_local_e2e_${checkoutCount}`,
    url: `https://checkout.stripe.com/c/pay/cs_test_local_e2e_${checkoutCount}`,
  };
};

function webhook(type, eventId, { live = false, checkoutRef = 'cs_test_local_e2e_1' } = {}) {
  const obj = type.startsWith('charge.')
    ? { object: 'charge', id: 'ch_local_e2e_001', payment_intent: 'pi_local_e2e_001' }
    : { object: 'checkout.session', id: checkoutRef };
  const payload = JSON.stringify({
    id: eventId,
    object: 'event',
    type,
    livemode: live,
    api_version: '2026-09-30.endive',
    created: Math.floor(Date.now() / 1000),
    data: { object: obj },
  });
  const signature = stripe.webhooks.generateTestHeaderString({ payload, secret });
  return new Request(`${baseUrl}/api/webhooks/stripe`, {
    method: 'POST',
    headers: { 'stripe-signature': signature },
    body: payload,
  });
}
function payFact(orderId, amount = PACK3.amount, overrides = {}) {
  return {
    provider: 'stripe',
    paymentRef: 'pi_local_e2e_001',
    chargeRef: 'pi_local_e2e_001',
    paid: true,
    amount,
    currency: PACK3.currency.toLowerCase(),
    amountRefunded: 0,
    dispute: null,
    metadataTrusted: true,
    userId: mainUser.id,
    orderId,
    productId: 'pack_3',
    subscriptionRef: null,
    periodStart: null,
    periodEnd: null,
    paidAt: Date.now(),
    fetchedAt: Date.now(),
    ...overrides,
  };
}
const queryOne = async (sql, values = []) => (await db.query(sql, values)).rows[0];
const count = async (sql, values = []) => Number(Object.values(await queryOne(sql, values))[0]);
const apiRequest = (path, data) =>
  new Request(baseUrl + path, {
    method: 'POST',
    headers: { origin: baseUrl, 'content-type': 'application/json' },
    body: JSON.stringify(data),
  });
async function run() {
  await db.query(
    'TRUNCATE public.owned_items,public.paid_ai_readings,public.unlocks,public.entitlements,public.payments,public.orders,public.webhook_events,public.profiles,auth.users RESTART IDENTITY CASCADE',
  );
  for (const user of [mainUser, otherUser]) {
    await db.query('INSERT INTO auth.users(id) VALUES ($1)', [user.id]);
    await db.query('INSERT INTO public.profiles(id,email) VALUES ($1,$2)', [user.id, user.email]);
  }
  assert.equal(await count('SELECT count(*)::integer FROM public.sticks'), 100);
  assert.equal(await count('SELECT count(*)::integer FROM public.stick_locales'), 100);
  console.log('PASS: 100 traditional fortune sticks and 100 Simplified variants in isolated PostgreSQL');

  assert.equal((await accountSnapshot(db, null, false, false)).status, 401);
  const checkout = await createTestCheckout({
    site,
    provider,
    database: db,
    user: mainUser,
    baseUrl,
    request: apiRequest('/api/billing/checkout', {
      productId: 'pack_3',
      locale: 'zh-Hant',
      currency: PACK3.currency,
    }),
  });
  assert.equal(checkout.status, 201, await checkout.clone().text());
  const receipt = await checkout.json();
  const orderId = receipt.orderId;
  assert.match(orderId, /^[0-9a-f-]{36}$/i);
  assert.match(receipt.checkoutUrl, /^https:\/\/checkout\.stripe\.com\//);
  const pending = await queryOne(
    'SELECT status,amount,currency,checkout_ref FROM public.orders WHERE id=$1',
    [orderId],
  );
  assert.equal(pending.status, 'pending');
  assert.equal(Number(pending.amount), PACK3.amount);
  assert.equal(pending.currency, PACK3.currency);
  assert.equal(pending.checkout_ref, 'cs_test_local_e2e_1');
  console.log(
    'PASS: Checkout created correct server-priced order, persistent Stripe customer and return origin',
  );

  const fact = payFact(orderId);
  provider.fetchCheckout = async () => ({ orderId, subscription: null, payment: fact });
  const first = await settleStripeWebhook({
    site,
    provider,
    supabase: db,
    request: webhook('checkout.session.completed', 'evt_local_paid_1'),
  });
  assert.equal(first.status, 200, await first.clone().text());
  assert.equal((await queryOne('SELECT status FROM public.orders WHERE id=$1', [orderId])).status, 'paid');
  assert.equal(
    await count('SELECT count(*)::integer FROM public.entitlements WHERE order_id=$1', [orderId]),
    1,
  );
  console.log('PASS: HMAC-signed paid event settled into SQL, granted exactly one pack');

  const replays = await Promise.all([
    settleStripeWebhook({
      site,
      provider,
      supabase: db,
      request: webhook('checkout.session.completed', 'evt_local_paid_1'),
    }),
    settleStripeWebhook({
      site,
      provider,
      supabase: db,
      request: webhook('checkout.session.async_payment_succeeded', 'evt_local_paid_2'),
    }),
    settleStripeWebhook({
      site,
      provider,
      supabase: db,
      request: webhook('checkout.session.completed', 'evt_local_paid_3'),
    }),
  ]);
  assert.ok(replays.every((r) => r.status === 200));
  assert.equal(
    await count('SELECT count(*)::integer FROM public.entitlements WHERE order_id=$1', [orderId]),
    1,
  );
  assert.equal(await count('SELECT count(*)::integer FROM public.payments WHERE order_id=$1', [orderId]), 1);
  console.log('PASS: concurrent Stripe event IDs cannot double-grant or duplicate payment');

  const pack = await queryOne('SELECT id,total_uses,used_uses FROM public.entitlements WHERE order_id=$1', [
    orderId,
  ]);
  assert.equal(pack.total_uses, 3);
  const env = {
    AI_ENABLE_TEST_GENERATION: 'true',
    OPENAI_API_KEY: 'sk-local-fake',
    OPENAI_MODEL: 'qa-model',
  };
  const redeem = () =>
    redeemPackRequest(
      apiRequest('/api/account/redeem', { packId: pack.id, stickId: 8, category: 'him', locale: 'zh-Hant' }),
      db,
      mainUser,
      env,
    );
  const redeemed = await redeem();
  if (redeemed.status !== 201) console.log('REDEEM_ERROR', redeemed.status, await redeemed.clone().text());
  assert.equal(redeemed.status, 201);
  assert.equal((await redeem()).status, 201);
  assert.equal(
    (await queryOne('SELECT used_uses FROM public.entitlements WHERE id=$1', [pack.id])).used_uses,
    1,
  );
  assert.equal(
    await count(
      "SELECT count(*)::integer FROM public.unlocks WHERE user_id=$1 AND stick_id=8 AND category='him'",
      [mainUser.id],
    ),
    1,
  );
  console.log('PASS: repeated pack redemption did not consume another use');

  const report = [
    '籤詩意象：這是以傳統籤詩作為文化隱喻的解讀，不代表我們能得知別人的私心或未來。',
    '關係觀察：可參考你自己真正看到的相處細節，例如對方是否尊重約定，而不是憑猜測定罪。',
    '可以嘗試的一步：主動詢問彼此有沒有時間交換感受，用溫和、明確而尊重彼此自主的方式溝通。',
    '界線提醒：不要監視、操控或反覆糾纏，保留自我照顧與退出的空間。',
    '此解讀是 AI 生成的文化與自我反思內容，不代表現實預測。',
  ].join('\n\n');
  assert.ok(report.length > 100);
  const mockAiFetch = async (_url, options) => {
    aiCalls++;
    const payload = JSON.parse(options.body);
    assert.equal(payload.store, false);
    assert.equal(payload.model, 'qa-model');
    assert.ok(payload.input.includes('請問怎樣開口比較合適'));
    return new Response(
      JSON.stringify({
        status: 'completed',
        output: [{ type: 'message', content: [{ type: 'output_text', text: report }] }],
      }),
      { status: 200, headers: { 'content-type': 'application/json' } },
    );
  };
  const input = { stickId: 8, category: 'him', locale: 'zh-Hant', question: '請問怎樣開口比較合適' };
  const generate = () =>
    generatePaidReading({
      user: mainUser,
      input,
      database: db,
      apiKey: 'sk-local-fake',
      model: 'qa-model',
      fetchImpl: mockAiFetch,
    });
  assert.equal((await generate()).status, 200);
  assert.equal((await generate()).status, 200);
  assert.equal(aiCalls, 1);
  const read = (user = mainUser) =>
    paidReadingResponse(
      new Request(`${baseUrl}/api/account/reading?stickId=8&category=him&locale=zh-Hant`),
      db,
      user,
    );
  const own = await read();
  assert.equal(own.status, 200);
  assert.equal((await own.json()).body, report);
  assert.equal((await read(otherUser)).status, 404);
  const stored = await queryOne('SELECT status,body,model FROM public.paid_ai_readings WHERE user_id=$1', [
    mainUser.id,
  ]);
  assert.equal(stored.status, 'ready');
  assert.equal(stored.body, report);
  assert.equal(stored.model, 'qa-model');
  console.log('PASS: private AI report saved once, re-read without re-generating, another user denied');

  const snapshot = await accountSnapshot(db, mainUser, false, true);
  assert.equal(snapshot.status, 200);
  const acc = await snapshot.json();
  assert.equal(acc.orders[0].status, 'paid');
  assert.equal(acc.packs[0].remaining_uses, 2);
  assert.equal(acc.unlocks.length, 1);
  console.log('PASS: account shows paid order, live pack balance and own private unlock');

  provider.fetchPaymentByCharge = async () =>
    payFact(orderId, PACK3.amount, { amountRefunded: 100, fetchedAt: Date.now() + 3000 });
  const refund = await settleStripeWebhook({
    site,
    provider,
    supabase: db,
    request: webhook('charge.refunded', 'evt_local_refund_1'),
  });
  assert.equal(refund.status, 200, await refund.clone().text());
  assert.equal((await read()).status, 404);
  assert.equal(
    (await queryOne('SELECT revoked FROM public.unlocks WHERE user_id=$1 AND stick_id=8', [mainUser.id]))
      .revoked,
    true,
  );
  const frozen = await queryOne('SELECT total_uses,used_uses FROM public.entitlements WHERE id=$1', [
    pack.id,
  ]);
  assert.equal(frozen.used_uses, frozen.total_uses);
  console.log('PASS: partial refund revokes redeemed content, freezes credits and removes AI report access');

  const another = await createTestCheckout({
    site,
    provider,
    database: db,
    user: mainUser,
    baseUrl,
    request: apiRequest('/api/billing/checkout', {
      productId: 'pack_3',
      locale: 'zh-Hant',
      currency: PACK3.currency,
    }),
  });
  assert.equal(another.status, 201);
  const underpaidOrder = (await another.json()).orderId;
  provider.fetchCheckout = async () => ({
    orderId: underpaidOrder,
    subscription: null,
    payment: payFact(underpaidOrder, 100, { paymentRef: 'pi_local_underpaid_001' }),
  });
  const underpaid = await settleStripeWebhook({
    site,
    provider,
    supabase: db,
    request: webhook('checkout.session.completed', 'evt_local_underpaid'),
  });
  assert.equal(underpaid.status, 500);
  assert.equal(
    (await queryOne('SELECT status FROM public.orders WHERE id=$1', [underpaidOrder])).status,
    'pending',
  );
  assert.equal(
    await count('SELECT count(*)::integer FROM public.entitlements WHERE order_id=$1', [underpaidOrder]),
    0,
  );
  console.log('PASS: underpayment is rejected and cannot grant rights');

  // Failure / expiration must not leave payment attempts indefinitely pending.
  // Order status comes ONLY from a current provider-refetched checkout state.
  const third = await createTestCheckout({
    site,
    provider,
    database: db,
    user: mainUser,
    baseUrl,
    request: apiRequest('/api/billing/checkout', {
      productId: 'pack_3',
      locale: 'zh-Hant',
      currency: PACK3.currency,
    }),
  });
  assert.equal(third.status, 201);
  const failedId = (await third.json()).orderId;
  const failedRef = (await queryOne('SELECT checkout_ref FROM public.orders WHERE id=$1', [failedId]))
    .checkout_ref;
  provider.fetchCheckout = async (checkoutRef) => {
    assert.equal(checkoutRef, failedRef);
    return {
      orderId: failedId,
      status: 'complete',
      paymentStatus: 'unpaid',
      payment: null,
      subscription: null,
    };
  };
  const failedEvent = () =>
    webhook('checkout.session.async_payment_failed', 'evt_local_failed', {
      checkoutRef: failedRef,
    });
  assert.equal(
    (await settleStripeWebhook({ site, provider, supabase: db, request: failedEvent() })).status,
    200,
  );
  assert.equal(
    (await settleStripeWebhook({ site, provider, supabase: db, request: failedEvent() })).status,
    200,
  );
  assert.equal((await queryOne('SELECT status FROM public.orders WHERE id=$1', [failedId])).status, 'failed');
  assert.equal(
    await count('SELECT count(*)::integer FROM public.entitlements WHERE order_id=$1', [failedId]),
    0,
  );
  console.log('PASS: delayed failed payment closes order, is idempotent and never grants credits');

  const fourth = await createTestCheckout({
    site,
    provider,
    database: db,
    user: mainUser,
    baseUrl,
    request: apiRequest('/api/billing/checkout', {
      productId: 'pack_3',
      locale: 'zh-Hant',
      currency: PACK3.currency,
    }),
  });
  assert.equal(fourth.status, 201);
  const expiredId = (await fourth.json()).orderId;
  const expiredRef = (await queryOne('SELECT checkout_ref FROM public.orders WHERE id=$1', [expiredId]))
    .checkout_ref;
  provider.fetchCheckout = async (checkoutRef) => {
    assert.equal(checkoutRef, expiredRef);
    return {
      orderId: expiredId,
      status: 'expired',
      paymentStatus: 'unpaid',
      payment: null,
      subscription: null,
    };
  };
  const expiredRequest = () =>
    webhook('checkout.session.expired', 'evt_local_expired', { checkoutRef: expiredRef });
  assert.equal(
    (await settleStripeWebhook({ site, provider, supabase: db, request: expiredRequest() })).status,
    200,
  );
  assert.equal(
    (await queryOne('SELECT status FROM public.orders WHERE id=$1', [expiredId])).status,
    'expired',
  );
  assert.equal(
    await count('SELECT count(*)::integer FROM public.entitlements WHERE order_id=$1', [expiredId]),
    0,
  );
  console.log('PASS: expired unpaid Checkout is recorded without granting access');

  provider.fetchCheckout = async () => ({
    orderId,
    status: 'expired',
    paymentStatus: 'unpaid',
    payment: null,
    subscription: null,
  });
  const alreadyPaidExpired = await settleStripeWebhook({
    site,
    provider,
    supabase: db,
    request: webhook('checkout.session.expired', 'evt_local_paid_never_downgraded'),
  });
  assert.equal(alreadyPaidExpired.status, 200);
  assert.equal((await queryOne('SELECT status FROM public.orders WHERE id=$1', [orderId])).status, 'paid');
  console.log('PASS: late expiration cannot downgrade an already paid order');

  const privileges = await queryOne(
    "SELECT has_function_privilege('anon'," +
      "'public.settle_stripe_payment(text,text,text,text,text,uuid,uuid,text,bigint,text,boolean,bigint,text,text,timestamptz,timestamptz,timestamptz,timestamptz)','EXECUTE') AS anon_settle, " +
      "has_function_privilege('authenticated','public.claim_paid_ai_reading(uuid,smallint,text,text)','EXECUTE') AS auth_claim, " +
      "has_function_privilege('service_role','public.claim_paid_ai_reading(uuid,smallint,text,text)','EXECUTE') AS service_claim",
  );
  assert.equal(privileges.anon_settle, false);
  assert.equal(privileges.auth_claim, false);
  assert.equal(privileges.service_claim, true);
  console.log('PASS: anonymous and logged-in clients cannot directly execute money or AI grants');

  // ---- Owned items (kind: 'item'): checkout → webhook → ownership → no double sale → refund ----
  expecting = { id: ITEM.id, price: ITEM_PRICE };
  const itemBody = { productId: ITEM.id, locale: 'zh-Hant', currency: ITEM_PRICE.currency, from: 'market' };
  const withStick = await createTestCheckout({
    site: itemSite,
    provider,
    database: db,
    user: otherUser,
    baseUrl,
    request: apiRequest('/api/billing/checkout', { ...itemBody, stickId: 7, category: 'him' }),
  });
  assert.equal(withStick.status, 400);
  const unknown = await createTestCheckout({
    site: itemSite,
    provider,
    database: db,
    user: otherUser,
    baseUrl,
    request: apiRequest('/api/billing/checkout', { ...itemBody, productId: 'outfit_does_not_exist' }),
  });
  assert.equal(unknown.status, 404);
  console.log('PASS: item checkout rejects a stick selection and unknown product ids');

  provider.createCustomer = async () => 'cus_test_local_e2e_002';
  const itemCheckout = await createTestCheckout({
    site: itemSite,
    provider,
    database: db,
    user: otherUser,
    baseUrl,
    request: apiRequest('/api/billing/checkout', itemBody),
  });
  assert.equal(itemCheckout.status, 201, await itemCheckout.clone().text());
  const itemOrder = (await itemCheckout.json()).orderId;
  const itemRow = await queryOne('SELECT product_kind,amount,currency FROM public.orders WHERE id=$1', [
    itemOrder,
  ]);
  assert.equal(itemRow.product_kind, 'item');
  assert.equal(Number(itemRow.amount), ITEM_PRICE.amount);
  const itemFact = (overrides = {}) =>
    payFact(itemOrder, ITEM_PRICE.amount, {
      userId: otherUser.id,
      productId: ITEM.id,
      paymentRef: 'pi_local_item_001',
      chargeRef: 'pi_local_item_001',
      ...overrides,
    });
  provider.fetchCheckout = async () => ({ orderId: itemOrder, subscription: null, payment: itemFact() });
  for (const eventId of ['evt_local_item_paid', 'evt_local_item_paid', 'evt_local_item_paid_again']) {
    const settled = await settleStripeWebhook({
      site: itemSite,
      provider,
      supabase: db,
      request: webhook('checkout.session.completed', eventId),
    });
    assert.equal(settled.status, 200, await settled.clone().text());
  }
  assert.equal(
    await count(
      'SELECT count(*)::integer FROM public.owned_items WHERE user_id=$1 AND item_id=$2 AND NOT revoked',
      [otherUser.id, ITEM.id],
    ),
    1,
  );
  const ownerAccount = await (await accountSnapshot(db, otherUser, true, true)).json();
  assert.deepEqual(ownerAccount.items, [ITEM.id]);
  assert.deepEqual((await (await accountSnapshot(db, mainUser, true, true)).json()).items, []);
  console.log(
    'PASS: paid item is granted exactly once across replayed events and shows only in its owner’s account',
  );

  const second = await createTestCheckout({
    site: itemSite,
    provider,
    database: db,
    user: otherUser,
    baseUrl,
    request: apiRequest('/api/billing/checkout', itemBody),
  });
  assert.equal(second.status, 409);
  console.log('PASS: an owned item cannot be bought twice');

  provider.fetchPaymentByCharge = async () =>
    itemFact({ amountRefunded: ITEM_PRICE.amount, fetchedAt: Date.now() + 5000 });
  const itemRefund = await settleStripeWebhook({
    site: itemSite,
    provider,
    supabase: db,
    request: webhook('charge.refunded', 'evt_local_item_refund'),
  });
  assert.equal(itemRefund.status, 200, await itemRefund.clone().text());
  assert.deepEqual((await (await accountSnapshot(db, otherUser, true, true)).json()).items, []);
  const rebuy = await createTestCheckout({
    site: itemSite,
    provider,
    database: db,
    user: otherUser,
    baseUrl,
    request: apiRequest('/api/billing/checkout', itemBody),
  });
  assert.equal(rebuy.status, 201);
  console.log('PASS: refund takes the item back, and it can then be bought again');

  console.log('ALL LOCAL CHECKOUT → WEBHOOK → PACK → AI → REFUND → ITEM CHECKS PASSED');
}
try {
  await run();
} finally {
  await db.close();
}
